  rough = mix(0.44, 0.24, contrast(wear, 1.6));
  rough = mix(rough, 0.86, rust * 0.8);
  rough = mix(rough, 0.80, pits * 0.7);
  ao = 1.0 - (1.0 - clamp(height, 0.0, 1.0)) * 0.6;
